import java.util.*;
class Backtracking {static List<List<Integer>> queens(int n){List<List<Integer>> out=new ArrayList<>();queen(n,new ArrayList<>(),out);return out;}static void queen(int n,List<Integer> path,List<List<Integer>> out){int row=path.size();if(row==n){out.add(new ArrayList<>(path));return;}for(int col=0;col<n;col++){boolean valid=true;for(int r=0;r<row;r++)if(path.get(r)==col||Math.abs(path.get(r)-col)==row-r){valid=false;break;}if(valid){path.add(col);queen(n,path,out);path.remove(path.size()-1);}}}
static List<List<Integer>> subsets(int[] a){List<List<Integer>> out=new ArrayList<>();subset(a,0,new ArrayList<>(),out);return out;}static void subset(int[] a,int i,List<Integer> path,List<List<Integer>> out){if(i==a.length){out.add(new ArrayList<>(path));return;}subset(a,i+1,path,out);path.add(a[i]);subset(a,i+1,path,out);path.remove(path.size()-1);}
static List<List<Integer>> permutations(int[] a){List<List<Integer>> out=new ArrayList<>();permute(a,new boolean[a.length],new ArrayList<>(),out);return out;}static void permute(int[] a,boolean[] used,List<Integer> path,List<List<Integer>> out){if(path.size()==a.length){out.add(new ArrayList<>(path));return;}for(int i=0;i<a.length;i++)if(!used[i]){used[i]=true;path.add(a[i]);permute(a,used,path,out);path.remove(path.size()-1);used[i]=false;}}
static class Sudoku {int visits;boolean exhausted;final int[][] board;Sudoku(int[][] input){board=Arrays.stream(input).map(int[]::clone).toArray(int[][]::new);}boolean legal(int r,int c,int v){for(int i=0;i<9;i++)if(board[r][i]==v||board[i][c]==v)return false;for(int a=r/3*3;a<r/3*3+3;a++)for(int b=c/3*3;b<c/3*3+3;b++)if(board[a][b]==v)return false;return true;}
boolean solve(){if(++visits>3000){exhausted=true;return false;}int row=-1,col=-1;List<Integer> choices=null;for(int r=0;r<9;r++)for(int c=0;c<9;c++)if(board[r][c]==0){List<Integer> options=new ArrayList<>();for(int v=1;v<=9;v++)if(legal(r,c,v))options.add(v);if(options.isEmpty())return false;if(choices==null||options.size()<choices.size()){row=r;col=c;choices=options;}}if(row==-1)return true;for(int v:choices){board[row][col]=v;if(solve())return true;board[row][col]=0;if(exhausted)return false;}return false;}}
}
